Here’s a minimal Go‑sidecar that watches Vault, pulls a new key, updates an env var, and emits a SIGHUP so the host app can reload without a restart. 

```go
package main

import (
    "context"
    "fmt"
    "os"
    "os/signal"
    "syscall"
    "time"

    "github.com/hashicorp/vault/api"
)

func main() {
    // Vault client setup
    cfg := api.DefaultConfig()
    // Assume VAULT_ADDR and VAULT_TOKEN env vars
    client, err := api.NewClient(cfg)
    if err != nil {
        panic(err)
    }

    // Path and key field you want to poll
    path := "secret/data/api-keys"
    field := "encryption_key"

    // Channel to notify host app of a new key
    reloadCh := make(chan struct{})

    // Signal handler – host app should listen for SIGHUP
    sigCh := make(chan os.Signal, 1)
    signal.Notify(sigCh, syscall.SIGHUP)
    go func() {
        for range sigCh {
            fmt.Println("SIGHUP received – trigger reload")
            reloadCh <- struct{}{}
        }
    }()

    // Poll Vault every minute
    for {
        secret, err := client.Logical().Read(path)
        if err != nil {
            fmt.Println("Vault read error:", err)
            time.Sleep(30 * time.Second)
            continue
        }
        if secret == nil {
            fmt.Println("No secret found at", path)
            time.Sleep(30 * time.Second)
            continue
        }
        newKey := secret.Data["data"].(map[string]interface{})[field].(string)
        // Compare with current env var
        if os.Getenv("ENC_KEY") != newKey {
            os.Setenv("ENC_KEY", newKey)
            fmt.Println("Updated ENC_KEY – sending SIGHUP to host")
            // Emit SIGHUP to the main process (assumed PID 1 in container)
            sysProc := os.FindProcess(1)
            if err := sysProc.Signal(syscall.SIGHUP); err != nil {
                fmt.Println("Failed to signal host:", err)
            }
        }
        time.Sleep(1 * time.Minute)
    }
}
```

Deploy it as a sidecar next to your service, mount the Vault token via a secret, and your main app can simply listen for `SIGHUP` to reload the key. This keeps the key lifecycle out of code, reduces redeploy churn, and adheres to the 90‑day rotation schedule you set in the main post.

Happy rotating! 🚀

