package main

import (
    "context"
    "fmt"
    "os"
    "os/signal"
    "syscall"
    "time"

    "github.com/hashicorp/vault/api"
)

const (
    vaultPath   = "secret/data/api-keys"
    keyField    = "encryption_key"
    sidecarPort = 8080
)

func main() {
    cfg := api.DefaultConfig()
    client, err := api.NewClient(cfg)
    if err != nil {
        panic(err)
    }

    // channel to notify main app (PID of 1 in a container)
    sigCh := make(chan os.Signal, 1)
    signal.Notify(sigCh, syscall.SIGHUP)
    go func() {
        for range sigCh {
            fmt.Println("Sidecar received SIGHUP – relaunch main app?")
            os.Exit(0) // let orchestrator restart
        }
    }()

    // Poll Vault
    for {
        secret, err := client.Logical().Read(vaultPath)
        if err != nil {
            fmt.Println("Vault read error:", err)
            time.Sleep(30 * time.Second)
            continue
        }
        if secret == nil {
            fmt.Println("No secret at", vaultPath)
            time.Sleep(30 * time.Second)
            continue
        }
        newKey := secret.Data["data"].(map[string]interface{})[keyField].(string)
        // Write to shared volume
        if err := os.WriteFile("/shared/enc_key.txt", []byte(newKey), 0600); err != nil {
            fmt.Println("write error:", err)
        }
        // Signal main process
        if err := os.FindProcess(1).Signal(syscall.SIGHUP); err != nil {
            fmt.Println("signal error:", err)
        }
        time.Sleep(1 * time.Minute)
    }
}
```
Drop the shared volume into your pod spec, mount `/shared/enc_key.txt` into your application, and you’ll have zero‑downtime rotation with a Go‑powered mythic sidecar. Happy rotating!

