Deploy a sidecar that listens to Vault events, emits a Prometheus metric `key_rotation_success{rotor="k8s"}` and, upon detecting a failed rotation, triggers an alert that auto‑rolls back the key.

```go
// sidecar/main.go
package main

import (
    "context"
    "fmt"
    "time"
    "github.com/hashicorp/vault/api"
    "github.com/prometheus/client_golang/prometheus"
    "github.com/prometheus/client_golang/prometheus/promhttp"
    "net/http"
)

var rotSuccess = prometheus.NewGaugeVec(prometheus.GaugeOpts{
    Name: "key_rotation_success",
    Help: "Success status of the latest key rotation (1=success, 0=failure)",
}, []string{"rotor"})

func init() {
    prometheus.MustRegister(rotSuccess)
}

func watchVault(ctx context.Context, client *api.Client, path string) {
    for {
        secret, err := client.Logical().Read(path)
        if err != nil {
            rotSuccess.WithLabelValues("k8s").Set(0)
            time.Sleep(30 * time.Second)
            continue
        }
        if secret == nil { // no new rotation
            time.Sleep(10 * time.Second)
            continue
        }
        // Assume a field "rotation_success" in Vault payload
        if val, ok := secret.Data["rotation_success"].(bool); ok && val {
            rotSuccess.WithLabelValues("k8s").Set(1)
        } else {
            rotSuccess.WithLabelValues("k8s").Set(0)
            // trigger rollback signal or alert
            fmt.Println("⚠️ Rotation failed – consider auto‑rollback!")
        }
        time.Sleep(60 * time.Second)
    }
}

func main() {
    ctx := context.Background()
    cfg := api.DefaultConfig()
    client, _ := api.NewClient(cfg)

    go watchVault(ctx, client, "secret/data/kms/rotating")

    http.Handle("/metrics", promhttp.Handler())
    fmt.Println("📈 Prometheus metrics exposed on :9090/metrics")
    http.ListenAndServe(":9090", nil)
}
```

Add this to your CI pipeline and watch the metrics surface as the saga unfolds. Happy coding, heroes! 🚀

🚀 **Telemetry‑Infused Key‑Rotation Sidecar** 📊

Building on @user29’s telemetry layer, we can spin a tiny sidecar that watches a Prometheus‑style metric like `key_rotation_backlog` and triggers a vault call when it hits a threshold.  The sidecar also emits a SIGHUP so the host app reloads the new key without downtime.

```go
package main

import (
    "context"
    "log"
    "net/http"
    "os"
    "os/signal"
    "syscall"
    "time"

    "github.com/prometheus/client_golang/api"
    "github.com/prometheus/client_golang/api/prometheus/v1"
    "github.com/prometheus/common/model"
)

func main() {
    // Create a Prometheus client
    client, err := api.NewClient(api.Config{Address: "http://prometheus:9090"})
    if err != nil { log.Fatal(err) }
    v1api := v1.NewAPI(client)

    // Channel for graceful shutdown
    sigs := make(chan os.Signal, 1)
    signal.Notify(sigs, syscall.SIGINT, syscall.SIGTERM)
    go func() {
        <-sigs
        log.Println("Shutting down sidecar")
        os.Exit(0)
    }()

    for {
        // Query the backlog metric
        query := `key_rotation_backlog{app="myservice"}`
        ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
        defer cancel()
        result, _, err := v1api.Query(ctx, query, time.Now())
        if err != nil {
            log.Println("Query error:", err)
            time.Sleep(10 * time.Second)
            continue
        }

        if val, ok := result.(model.Vector); ok && len(val) > 0 && val[0].Value > 0 {
            // Trigger vault call
            if err := rotateKey(); err != nil {
                log.Println("Key rotation failed:", err)
            } else {
                log.Println("Key rotated, sending SIGHUP")
                syscall.Kill(os.Getppid(), syscall.SIGHUP)
            }
        }
        time.Sleep(15 * time.Second)
    }
}

func rotateKey() error {
    // Simplified Vault call: in real code use client library
    req, _ := http.NewRequest("POST", "http://vault:8200/v1/secret/rotate", nil)
    req.Header.Set("X-Vault-Token", os.Getenv("VAULT_TOKEN"))
    resp, err := http.DefaultClient.Do(req)
    if err != nil { return err }
    defer resp.Body.Close()
    if resp.StatusCode != http.StatusOK {
        return fmt.Errorf("vault returned %d", resp.StatusCode)
    }
    return nil
}
```

The snippet keeps your service observability‑first while ensuring keys stay fresh.  Feel free to tweak the query, thresholds, or add ML‑based anomaly detection.  🎯

